package com.mhtextractor.uiport;

import com.fasterxml.jackson.annotation.JsonInclude;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * 端口事件（sealed）：工作区结构变更 / 运行状态 / 提醒。
 *
 * <p>文案一律「键 + 具名参数」（方案 §14 决策 13），渲染属前端；本包不得依赖任何国际化工具类。</p>
 */
public sealed interface PortEvent {

    /**
     * 参数状态变更类别（B4）：后端参数命令完成「写入 + 撤销压栈 + 磁盘缓存失效（规则 a）」后
     * 按此类别发布 {@link ParamStateChanged}；前端据此决定列表刷新与参数色刷新的粒度。
     */
    enum ParamChangeKind {
        /** 全局已确认参数写入（{@code applyConfirmedParams} 语义）：全部条目受影响 */
        SET_GLOBAL,
        /** One batch of backend-resolved targets, with one undo record. */
        SET_TARGETS,
        /** 组参数写入（{@code applyGroupParams} 语义）：该组未移除成员受影响 */
        SET_GROUP,
        /** 条目级参数写入（{@code applyItemParams} 语义）：该条目受影响 */
        SET_ITEM,
        /** 目标生效参数应用到全局（{@code applyGlobalParamsTo} 语义）：全部条目受影响 */
        APPLY_GLOBAL,
        /** 清除参数（{@code clearParamsForTargets} 语义，单条撤销）：被清除目标及组内成员受影响 */
        CLEAR
    }

    /**
     * 参数状态变更（B4）：后端已完成参数写入、撤销压栈与磁盘缓存失效；
     * 前端按 {@link #kind()} 执行对应的列表刷新与参数色刷新链（事件在命令线程同步送达）。
     *
     * @param kind          变更类别
     * @param imageMode     本次变更作用的模式（true = 图片，false = 文本）
     * @param affectedPaths 受影响条目路径（SET_GLOBAL / APPLY_GLOBAL = 全部条目含已移除；
     *                      其余 = 实际受影响条目；不可变副本）
     */
    record ParamStateChanged(ParamChangeKind kind, boolean imageMode, List<String> affectedPaths)
            implements PortEvent {
        public ParamStateChanged {
            Objects.requireNonNull(kind, "kind");
            affectedPaths = List.copyOf(Objects.requireNonNull(affectedPaths, "affectedPaths"));
        }
    }

    /** 取消或全量预解析推进代际；接收方应丢弃旧代际的排队回调。 */
    record WorkspaceActivityChanged(long generation) implements PortEvent {}

    record PreparseProgress(long generation, int done, int total) implements PortEvent {}

    // ---- B5-1：导入编排事件 ----

    /**
     * 导入在途状态变更（B5-1）：{@code importPaths} 建会话后置 true（前端置位「导入中」并禁用开始提取）；
     * 收尾唯一恢复点置 false。generation = 导入会话代际（每次 {@code importPaths} 自增）。
     */
    record ImportStateChanged(long generation, boolean importing) implements PortEvent {}

    /**
     * 一轮导入落地（B5-1）：后端已完成本轮全部模型命令（建组/平铺/追加）与撤销压栈
     * （<b>每轮恰好一条</b>，BC-5），前端据此执行列表全量刷新（每轮一次，RISK-8）、
     * 新建组的名字刷新挂接（F8/RISK-11）与「首轮列表由空转非空」的首行选中。
     *
     * @param generation       导入会话代际
     * @param plan             本轮计划（端口视图模型；含配额/剩余标志）
     * @param newFiles         本轮实际落地的新条目数（已去重；跳过的批次不计）
     * @param newGroups        本轮自动新建的组数
     * @param madeListNonEmpty 本轮首个非跳过批次应用前列表为空（导入首轮选中首行的判定）
     * @param createdGroups    本轮新建的组（模型对象，按落地顺序；前端挂接名字刷新监听）
     * @param groupSnapshots   IPC 新建组的不可变 VM；IPC 不重造模型身份，createdGroups 留空
     */
    record ImportRound(long generation, ImportPlanVm plan, int newFiles, int newGroups,
                       boolean madeListNonEmpty,
                       List<com.mhtextractor.model.GroupItem<com.mhtextractor.model.PreviewItem>> createdGroups,
                       @JsonInclude(JsonInclude.Include.NON_EMPTY) List<GroupVm> groupSnapshots)
            implements PortEvent {
        public ImportRound(long generation, ImportPlanVm plan, int newFiles, int newGroups,
                           boolean madeListNonEmpty,
                           List<com.mhtextractor.model.GroupItem<com.mhtextractor.model.PreviewItem>> createdGroups) {
            this(generation, plan, newFiles, newGroups, madeListNonEmpty, createdGroups, List.of());
        }
        public ImportRound {
            createdGroups = List.copyOf(Objects.requireNonNull(createdGroups, "createdGroups"));
            groupSnapshots = List.copyOf(groupSnapshots);
        }
    }

    /**
     * 导入收尾（B5-1）：载荷 = 本次导入全量累计条目的绝对路径（RISK-7：导入期间抑制、
     * 收尾跑一次，避免 O(n²)）。前端判「非空 + 当前模式参数已确认」后调
     * {@code commands().startPreparseFor(paths)} —— 与迁移前 {@code hasConfirmedParams} 门同语义。
     */
    record ImportFinished(long generation, List<String> accumulatedPaths) implements PortEvent {
        public ImportFinished {
            accumulatedPaths = List.copyOf(Objects.requireNonNull(accumulatedPaths, "accumulatedPaths"));
        }
    }

    record PreparseStarted(long generation) implements PortEvent {}

    /** 每完成一个条目交付一次，包括解析失败；不是整批结束通知。 */
    record PreparseFinished(long generation, PreparseResult result) implements PortEvent {}

    /** generation 是独立的预览请求代际；旧任务不得终结新任务的在途状态。 */
    record PreviewLoadStateChanged(long generation, String path, boolean active) implements PortEvent {}

    record PreviewConfirmationRequired(String path, String name, long sizeMiB) implements PortEvent {}

    record PreviewLoadFailed(long generation, String path, boolean fileInfo, String detail) implements PortEvent {}

    /** imageFile != null selects the IPC encoded-file representation; local pixels remain frontend-owned. */
    record PreviewThumbnail(long generation, String path, int index,
                            com.mhtextractor.model.ThumbnailData thumbnail,
                            @JsonInclude(JsonInclude.Include.NON_NULL) ImageFile imageFile) implements PortEvent {
        public PreviewThumbnail(long generation, String path, int index, com.mhtextractor.model.ThumbnailData thumbnail) {
            this(generation, path, index, thumbnail, null);
        }
    }

    /** Encoded original cache image, with its real format. The frontend decodes/scales it locally. */
    record ImageFile(String path, long bytes, String mediaType, String extension, String coreName,
                     int width, int height, int index,
                     @JsonInclude(JsonInclude.Include.NON_NULL) String displayName,
                     @JsonInclude(JsonInclude.Include.NON_NULL) Dimensions dimensions,
                     @JsonInclude(JsonInclude.Include.NON_NULL) String imagePath) {
        public record Dimensions(int width, int height) {}
        public ImageFile(String path, long bytes, String mediaType, String extension, String coreName,
                         int width, int height, int index, String displayName) {
            this(path, bytes, mediaType, extension, coreName, width, height, index, displayName,
                    new Dimensions(width, height), path);
        }
        public ImageFile(String path, long bytes, String mediaType, String extension, String coreName,
                         int width, int height, int index) {
            this(path, bytes, mediaType, extension, coreName, width, height, index, null, null, null);
        }
    }

    record PreviewPayload(String text, String html, List<ImageFile> images) {
        public PreviewPayload { images = List.copyOf(images); }
    }

    /** Terminal/repaint signal, also emitted on cancellation or stale completion.
     * A null thumbnail cache means return to the lazy prompt, never reenter loading. */
    record PreviewLoaded(long generation, String path,
                         @JsonInclude(JsonInclude.Include.NON_NULL) PreviewPayload payload) implements PortEvent {
        public PreviewLoaded(long generation, String path) { this(generation, path, null); }
    }

    record PreviewRegionConfirmationRequired(long generation, String path) implements PortEvent {}

    record PreviewNotice(long generation, String path, String key,
                         @JsonInclude(JsonInclude.Include.NON_EMPTY) Map<String,String> namedParams) implements PortEvent {
        public PreviewNotice(long generation, String path, String key) { this(generation,path,key,Map.of()); }
        public PreviewNotice { namedParams = Map.copyOf(namedParams); }
    }

    // ---- B6：提取任务通道（矩阵处置项 1）----

    /**
     * 提取任务通道事件族（B6）：任务代际 / 终态恰好一次 / 取消竞态 / 结果通道的端口契约 ——
     * {@link ExtractionProgress} / {@link ExtractionTerminal} / {@link ExtractionResult}
     * 都携带递增的 run 代际；旧任务迟到的投递由后端代际守卫拦下（不得污染新任务）。
     */
    non-sealed interface ExtractionChannelEvent extends PortEvent {
    }

    /**
     * 跨单元总进度（0.0~1.0，只增不减；后端 worker 的进度回调经派发器投递）。
     *
     * @param generation run 代际
     * @param overall    总进度
     */
    record ExtractionProgress(long generation, double overall) implements ExtractionChannelEvent {
    }

    /**
     * 提取终态（B6）：<b>恰好一次</b> —— 成功 / 失败在 worker 收尾后交付；取消在
     * {@code cancelExtraction()} 的<b>取消请求时刻</b>交付（取消请求 ≠ worker 已退出）。
     * 前端据此复位停止/开始按钮并渲染结果。
     *
     * @param generation          run 代际
     * @param end                 终态类别
     * @param stats               统计快照（仅 {@link ExtractionEnd#SUCCEEDED} 非 null；
     *                             取消路径的 partial 经 {@link ExtractionResult} 单独交付）
     * @param sessionOutputFolder 本次会话输出目录（成功路径"完成后打开输出目录"用）
     */
    record ExtractionTerminal(long generation, ExtractionEnd end,
                              com.mhtextractor.model.ExtractionStats stats,
                              String sessionOutputFolder) implements ExtractionChannelEvent {
    }

    /**
     * 取消路径的 partial 回写（B6）：worker 完成处理（取消请求之后）恰好投递一次，
     * 载荷 = worker 返回的统计；成功路径统计随 {@link ExtractionTerminal} 走，不重复投递。
     *
     * @param generation run 代际
     * @param stats      已处理单元的 partial 统计
     * @param sessionOutputFolder 本 run 请求冻结的会话输出目录
     */
    record ExtractionResult(long generation,
                            com.mhtextractor.model.ExtractionStats stats,
                            String sessionOutputFolder) implements ExtractionChannelEvent {
        public ExtractionResult(long generation, com.mhtextractor.model.ExtractionStats stats) {
            this(generation, stats, null);
        }
    }

    /** 提取终态类别（B6）：成功 / 失败 / 取消，每任务恰好交付其一。 */
    enum ExtractionEnd {
        /** worker 正常收尾（统计随终态事件交付） */
        SUCCEEDED,
        /** worker 异常收尾（无统计；后端已打 {@code log.maincontroller.37}，前端渲染错误卡片） */
        FAILED,
        /** 取消请求时刻交付（无统计；partial 经 {@link ExtractionResult} 在 worker 收尾后投递） */
        CANCELLED
    }

    /**
     * 工作区结构化变更（数据序 / 分组 / 勾选 / 参数 / 撤销等）。
     *
     * @param kind 变更类别（类别枚举留后续批次定稿；前端据此决定刷新粒度）
     */
    record WorkspaceChanged(String kind,
                            @JsonInclude(JsonInclude.Include.NON_NULL) WorkspaceVm snapshot,
                            @JsonInclude(JsonInclude.Include.NON_NULL) String undoKind,
                            @JsonInclude(JsonInclude.Include.NON_EMPTY) List<TargetId> affected,
                            @JsonInclude(JsonInclude.Include.NON_NULL) TargetId suggestedSelection) implements PortEvent {
        public WorkspaceChanged(String kind, WorkspaceVm snapshot) { this(kind, snapshot, null, List.of(), null); }
        public WorkspaceChanged(String kind) { this(kind, null); }
        public WorkspaceChanged {
            Objects.requireNonNull(kind, "kind");
            affected = List.copyOf(affected);
        }
    }

    /**
     * 提取在途状态变更。
     *
     * @param running 提取是否在途
     * @param generation run 代际；false 不表示 worker 已退出
     */
    record RunningChanged(boolean running, long generation) implements PortEvent {
        public RunningChanged(boolean running) { this(running, 0); }
    }

    /**
     * 提醒（前端按 {@link NoticeLevel} 选择呈现形式：错误居中必点 / 警告·信息右上 toast）。
     *
     * @param key         文案键
     * @param namedParams 具名参数（防御性不可变拷贝）
     * @param level       级别
     */
    record Notice(String key, Map<String, String> namedParams, NoticeLevel level) implements PortEvent {
        public Notice {
            Objects.requireNonNull(key, "key");
            namedParams = Map.copyOf(Objects.requireNonNull(namedParams, "namedParams"));
            Objects.requireNonNull(level, "level");
        }
    }
}
package com.mhtextractor.app;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.ParamScope;
import com.mhtextractor.model.PreviewItem;
import com.mhtextractor.model.ThumbnailData;
import com.mhtextractor.uiport.Confirmer;
import com.mhtextractor.uiport.Uiport;
import java.nio.file.Path;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;
import java.util.function.Supplier;

/** Explicit in-process assembly for tests and the opt-in fallback. Owns all business state. */
public final class BackendWorkspace implements AutoCloseable {
    private final WorkspaceModel model = new WorkspaceModel();
    private final GlobalParameterCache globals = new GlobalParameterCache();
    private final PreviewSession previews;
    private final WorkspaceActivityService activities;
    private final WorkspaceExtractionCoordinator extractions;
    private final WorkspaceParamService caches;
    private final InProcessUiport port;

    public BackendWorkspace(Confirmer confirmer, Supplier<AppConfig> runtime, Consumer<Runnable> dispatcher) {
        previews = PreviewSession.create(Path.of(System.getProperty("java.io.tmpdir"),
                "mht-extractor-preview", "workspace-" + UUID.randomUUID()));
        previews.startupCleanup();
        caches = new WorkspaceParamService(previews.lifecycle());
        var plans = new ExtractionPlanService(new ExtractionPlanService.Context() {
            public List<Object> dataOrder() { return model.topLevel(); }
            public boolean imageMode() { return runtime.get().isImageModeEnabled(); }
            public AppConfig textParamsCache() { return globals.text(); }
            public AppConfig imageParamsCache() { return globals.image(); }
            public String inputFolder() { return runtime.get().getInputFolder(); }
            public String outputFolder() { return runtime.get().getOutputFolder(); }
            public boolean openFolderAfterComplete() { return runtime.get().isOpenFolderAfterComplete(); }
        });
        activities = new WorkspaceActivityService(new WorkspaceActivityService.Context() {
            public List<PreviewItem> items() { return model.allItems(); }
            public boolean textMode() { return !runtime.get().isImageModeEnabled(); }
            public AppConfig effectiveParams(PreviewItem item) { return plans.effectiveParams(item); }
            public AppConfig effectiveImageParams(PreviewItem item) { return plans.effectiveImageParams(item); }
        }, new PreviewService(previews.lifecycle()), (image, index, config) -> {
            String ext = PreviewNamingService.detectExtension(image.data(), "jpg");
            int[] size = InProcessUiport.imageDimensions(image.data(), ext);
            return new ThumbnailData(PreviewNamingService.imageFileName(image, ext,
                    config.isEnableBatchRenaming(), index + 1, ""), size[0], size[1], null);
        }, dispatcher::accept);
        var clipboard = new ParamClipboard(model::push, target -> ParamScope.GLOBAL,
                (target, mode, config) -> { throw new UnsupportedOperationException("Use parameter commands"); });
        var parameters = new WorkspaceParamCommandService(model, caches, globals, clipboard::pushParamUndo);
        extractions = new WorkspaceExtractionCoordinator(new WorkspaceExtractionService(previews.lifecycle()),
                WorkspaceExtractionCoordinator.productionRequests(plans,
                        () -> model.allItems().stream().filter(item -> !item.removed).toList(), confirmer), dispatcher);
        port = new InProcessUiport(model, confirmer, plans, activities, parameters,
                new WorkspaceImportCoordinator(model, confirmer, dispatcher), extractions, caches, globals, previews);
    }

    public Uiport port() { return port; }

    @Override public void close() {
        activities.cancelWorkspaceActivity();
        activities.cancelPreviewLoad();
        extractions.cancelExtraction();
        var run=extractions.channel();
        if(run!=null)try{run.result.get(20,java.util.concurrent.TimeUnit.SECONDS);}
            catch(Exception error){throw new IllegalStateException("Extraction worker did not finish before cleanup",error);}
        activities.awaitPreviewInFlight(2_000);
        caches.clearAllCaches();
    }
}
package com.mhtextractor.uicore;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.uiport.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/** Serial business requests and atomic UI snapshots; progress and stop do not wait behind snapshot queries. */
public final class FrontendPort implements Uiport, AutoCloseable {
    private volatile Uiport backend;
    private final Consumer<Runnable> ui;
    private final Consumer<AppConfig> requestContext;
    private final boolean deferQueriesWhileBusy;
    private final ExecutorService requests=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"frontend-port");t.setDaemon(true);return t;});
    private final List<Consumer<PortEvent>> listeners=new CopyOnWriteArrayList<>();
    private AutoCloseable subscription;
    private volatile Predicate<Throwable> unavailable=error->false;
    private volatile Runnable unavailableAction=()->{};
    private final java.util.concurrent.atomic.AtomicLong connectionVersion=new java.util.concurrent.atomic.AtomicLong();
    private volatile PortSnapshot snapshot;
    private Supplier<AppConfig> runtime=AppConfig::new;
    private volatile AppConfig lastRuntime=new AppConfig();
    private Consumer<Throwable> failure=Throwable::printStackTrace;
    private final java.util.concurrent.atomic.AtomicBoolean running=new java.util.concurrent.atomic.AtomicBoolean();
    private final java.util.concurrent.atomic.AtomicBoolean closed=new java.util.concurrent.atomic.AtomicBoolean();
    private final java.util.concurrent.atomic.AtomicReference<com.mhtextractor.model.ExtractionStats> stats=new java.util.concurrent.atomic.AtomicReference<>();
    private final java.util.concurrent.atomic.AtomicLong eventVersion=new java.util.concurrent.atomic.AtomicLong();
    private PortSnapshot eventSnapshot;
    private long eventSnapshotVersion=-1;
    private volatile WorkspaceVm eventWorkspace;
    private volatile boolean importing,extracting,previewing,preparsing;
    private volatile long importGeneration,extractionGeneration,previewGeneration,activityGeneration;
    private volatile String loadingPath;

    public FrontendPort(Uiport backend, Consumer<Runnable> ui, Consumer<AppConfig> requestContext) {
        this(backend,ui,requestContext,false);
    }
    public FrontendPort(Uiport backend, Consumer<Runnable> ui, Consumer<AppConfig> requestContext,boolean deferQueriesWhileBusy) {
        this.backend=Objects.requireNonNull(backend);this.ui=ui;this.requestContext=requestContext;
        this.deferQueriesWhileBusy=deferQueriesWhileBusy;
        subscribe(backend);
    }
    private void subscribe(Uiport source) {
        subscription=source.events().subscribe(event->{if(closed.get()||backend!=source)return;
            boolean wasBusy=busy();observeActivity(event);eventVersion.incrementAndGet();
            if(event instanceof PortEvent.ExtractionProgress || event instanceof PortEvent.PreparseProgress){
                ui.accept(()->{if(!closed.get()&&backend==source)for(var listener:listeners)listener.accept(event);});
                if(wasBusy&&!busy())enqueue(this::refreshWhenIdle);
                return;
            }
            enqueue(()->{
            if(closed.get()||backend!=source)return;
            try { requestContext.accept(lastRuntime);
                var state=deferQueriesWhileBusy&&(busy()||event instanceof PortEvent.WorkspaceChanged) ? activitySnapshot()
                        : eventSnapshotVersion==eventVersion.get()?eventSnapshot:refreshSnapshot(lastRuntime);
                ui.accept(()->{if(closed.get()||backend!=source)return;snapshot=state;running.set(state.workspace().details().running());
                    if(event instanceof PortEvent.ExtractionTerminal end&&end.stats()!=null)stats.set(end.stats());
                    if(event instanceof PortEvent.ExtractionResult end&&end.stats()!=null)stats.set(end.stats());
                    for(var listener:listeners)listener.accept(event);});
            } catch(Throwable error){reportFailure(error,false);}
        });});
    }
    /** Called by the runtime's startup worker, before constructing the FXML controller. */
    public void bootstrap(AppConfig context) {lastRuntime=context;requestContext.accept(context);snapshot=refreshSnapshot(context);}
    /** A disconnected projection is UI data only; it never executes business commands locally. */
    public void bootstrapUnavailable(PortSnapshot empty) {snapshot=Objects.requireNonNull(empty);}
    public void onUnavailable(Predicate<Throwable> detection,Runnable action) {unavailable=detection;unavailableAction=action;}
    private void reportFailure(Throwable error,boolean requested) {
        reportFailure(error,requested,unavailableAction);
    }
    private void reportFailure(Throwable error,boolean requested,Runnable action) {
        if(closed.get())return;
        long version=connectionVersion.get();
        ui.accept(()->{if(closed.get()||version!=connectionVersion.get())return;
            if(unavailable.test(error)){if(requested)action.run();}
            else failure.accept(error);
        });
    }
    /** Keep the frontend handle and its subscribers; discard queued work from the old connection. */
    public CompletableFuture<Void> replaceBackend(Uiport replacement) {
        var done=new CompletableFuture<Void>();
        connectionVersion.incrementAndGet();
        if(closed.get()){done.completeExceptionally(new IllegalStateException("Frontend closed"));return done;}
        enqueue(()->{
            try {
                if(closed.get())throw new IllegalStateException("Frontend closed");
                subscription.close();backend=replacement;
                importing=extracting=previewing=preparsing=false;loadingPath=null;
                eventSnapshot=null;eventSnapshotVersion=-1;eventWorkspace=null;eventVersion.incrementAndGet();
                subscribe(replacement);var state=refreshSnapshot(lastRuntime);
                ui.accept(()->{if(closed.get()){done.completeExceptionally(new IllegalStateException("Frontend closed"));return;}
                    snapshot=state;running.set(state.workspace().details().running());stats.set(null);
                    for(var listener:listeners)listener.accept(new PortEvent.WorkspaceChanged("FRONTEND_REFRESH",state.workspace()));
                    done.complete(null);
                });
            }catch(Throwable error){done.completeExceptionally(error);}
        });
        return done;
    }
    public void bindRuntime(Supplier<AppConfig> runtime, Consumer<Throwable> failure) {this.runtime=runtime;this.failure=failure;}
    public Uiport implementation() {return backend;}
    public java.util.concurrent.atomic.AtomicBoolean runningView(){return running;}
    public java.util.concurrent.atomic.AtomicReference<com.mhtextractor.model.ExtractionStats> statsView(){return stats;}
    public PortSnapshot snapshot() {return Objects.requireNonNull(snapshot,"Port snapshot is not ready");}
    public <T> void execute(Function<Uiport,T> operation, Consumer<T> finished) {
        execute(operation,finished,true);
    }
    private <T> void execute(Function<Uiport,T> operation, Consumer<T> finished, boolean notify) {
        request(operation,finished,notify,true);
    }
    private <T> void request(Function<Uiport,T> operation, Consumer<T> finished, boolean notify,boolean refresh) {
        request(operation,finished,notify,refresh,true);
    }
    private <T> void request(Function<Uiport,T> operation, Consumer<T> finished, boolean notify,boolean refresh,boolean requested) {
        AppConfig frozen=runtime.get();lastRuntime=frozen;
        Runnable unavailableForRequest=unavailableAction;
        long version=connectionVersion.get();
        enqueue(()->{
            if(closed.get()||version!=connectionVersion.get())return;
            try {requestContext.accept(frozen);T result=operation.apply(backend);var state=refresh?refreshSnapshot(frozen):null;
                ui.accept(()->{if(closed.get()||version!=connectionVersion.get())return;
                    if(state!=null){snapshot=state;running.set(state.workspace().details().running());
                        if(notify)for(var listener:listeners)listener.accept(new PortEvent.WorkspaceChanged("FRONTEND_REFRESH",state.workspace()));}
                    finished.accept(result);});
            }catch(Throwable error){if(version==connectionVersion.get())reportFailure(error,requested,unavailableForRequest);}
        });
    }
    private void enqueue(Runnable task) {
        if(closed.get())return;
        try{requests.execute(task);}catch(RejectedExecutionException error){if(!closed.get())throw error;}
    }
    private void command(Consumer<WorkspaceCommands> operation) {execute(p->{operation.accept(p.commands());return null;},ignored->{});}
    private void activity(Consumer<WorkspaceCommands> operation) {
        request(p->{operation.accept(p.commands());return null;},ignored->{},false,false);
    }
    /** Selection highlight is local UI; its ordered cleanup must not open a backend decision card. */
    public void cancelPreviewForSelection() {
        request(p->{p.commands().cancelPreviewLoad();return null;},ignored->{},false,false,false);
    }

    private boolean busy(){return importing||extracting||previewing||preparsing;}
    private void observeActivity(PortEvent event){
        if(event instanceof PortEvent.WorkspaceChanged change&&change.snapshot()!=null)eventWorkspace=change.snapshot();
        if(event instanceof PortEvent.ImportStateChanged change){importing=change.importing();importGeneration=change.generation();}
        if(event instanceof PortEvent.RunningChanged change){extracting=change.running();extractionGeneration=change.generation();}
        if(event instanceof PortEvent.ExtractionTerminal)extracting=false;
        if(event instanceof PortEvent.PreviewLoadStateChanged change){previewing=change.active();previewGeneration=change.generation();loadingPath=change.active()?change.path():null;}
        if(event instanceof PortEvent.WorkspaceActivityChanged change){activityGeneration=change.generation();preparsing=false;}
        if(event instanceof PortEvent.PreparseStarted change){activityGeneration=change.generation();preparsing=true;}
        if(event instanceof PortEvent.PreparseProgress change&&change.generation()==activityGeneration&&change.done()>=change.total())preparsing=false;
    }
    private PortSnapshot activitySnapshot(){
        var base=eventSnapshot!=null?eventSnapshot:snapshot();
        var source=eventWorkspace!=null?eventWorkspace:base.workspace();var d=source.details();
        var facts=new WorkspaceVm.Details(d.textConfirmed(),d.imageConfirmed(),activityGeneration,previewGeneration,
                loadingPath,importing,importGeneration,extracting,extractionGeneration,d.lastStats(),d.sessionOutputFolder());
        var workspace=new WorkspaceVm(source.groups(),source.topLevelItems(),source.canUndo(),source.undoDepth(),
                source.selection(),source.topLevelOrder(),facts);
        return new PortSnapshot(workspace,base.text(),base.image(),base.cache(),base.textSchema(),base.imageSchema(),
                base.presentation(),base.textBodies(),base.allUnits(),base.checkedUnits());
    }
    private void refreshWhenIdle(){
        if(closed.get()||busy())return;
        try{var state=refreshSnapshot(lastRuntime);ui.accept(()->{if(closed.get())return;snapshot=state;
            for(var listener:listeners)listener.accept(new PortEvent.WorkspaceChanged("FRONTEND_REFRESH",state.workspace()));});}
        catch(Throwable error){reportFailure(error,false);}
    }

    private PortSnapshot refreshSnapshot(AppConfig runtime) {
        long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(10);
        for(;;){
            if(deferQueriesWhileBusy&&busy()&&eventSnapshot!=null)return activitySnapshot();
            long version=eventVersion.get();
            try{
                var state=readSnapshot(runtime);
                if(eventVersion.get()!=version&&System.nanoTime()<deadline)continue;
                eventSnapshot=state;eventSnapshotVersion=version;
                if(eventVersion.get()==version){eventWorkspace=state.workspace();var d=state.workspace().details();
                    activityGeneration=d.activityGeneration();previewGeneration=d.previewGeneration();loadingPath=d.loadingPath();
                    importGeneration=d.importGeneration();extractionGeneration=d.extractionGeneration();}
                return state;
            }catch(RuntimeException error){
                // Drain earlier backend events before deciding whether this was a concurrent revision change.
                backend.queries().workspace();
                if(eventVersion.get()==version||System.nanoTime()>=deadline)throw error;
            }
        }
    }

    private void cancelExtractionNow() {
        if(closed.get())return;
        long version=connectionVersion.get();var source=backend;
        Runnable unavailableForRequest=unavailableAction;
        Thread.ofPlatform().daemon().name("frontend-stop").start(()->{
            try{if(version==connectionVersion.get())source.commands().cancelExtraction();}
            catch(Throwable error){if(version==connectionVersion.get())reportFailure(error,true,unavailableForRequest);}
        });
    }

    private PortSnapshot readSnapshot(AppConfig runtime) {
        try {
            var q=backend.queries();var workspace=q.workspace();
            var ids=new ArrayList<TargetId>();var paths=new ArrayList<String>();
            for(var group:workspace.groups()){ids.add(TargetId.ofGroup(group.no()));for(var item:group.members())if(!item.removed()){ids.add(TargetId.ofItem(item.id()));paths.add(item.id());}}
            for(var item:workspace.topLevelItems())if(!item.removed()){ids.add(TargetId.ofItem(item.id()));paths.add(item.id());}
            var text=q.parameterState(false,ids,TargetResolution.EXPLICIT);var image=q.parameterState(true,ids,TargetResolution.EXPLICIT);
            var presentation=q.presentation(paths,runtime);var bodies=new HashMap<String,String>();
            for(var entry:presentation)if(entry.textFile()!=null)bodies.put(entry.path(),Files.readString(Path.of(entry.textFile().path())));
            return new PortSnapshot(workspace,text,image,q.cacheState(),q.paramSchema(false),q.paramSchema(true),presentation,bodies,q.outputUnitPlan(false),q.outputUnitPlan(true));
        }catch(java.io.IOException error){throw new java.io.UncheckedIOException(error);}
    }
    @Override public Confirmer confirmer(){return backend.confirmer();}
    @Override public PortEvents events(){return listener->{listeners.add(listener);return ()->listeners.remove(listener);};}
    @Override public WorkspaceQueries queries(){return queries;}
    private final WorkspaceQueries queries=new WorkspaceQueries(){
        public WorkspaceVm workspace(){return snapshot().workspace();}
        public long activityGeneration(){return workspace().details().activityGeneration();}
        public long previewGeneration(){return workspace().details().previewGeneration();}
        public String previewLoadingPath(){return workspace().details().loadingPath();}
        public AppConfig runtimeConfig(){return lastRuntime;}
        public List<OutputUnitVm> outputUnitPlan(boolean checked){return checked?snapshot().checkedUnits():snapshot().allUnits();}
        public ParamSchemaVm paramSchema(boolean image){return image?snapshot().imageSchema():snapshot().textSchema();}
        public CacheStateVm cacheState(){return snapshot().cache();}
        public ParameterStateVm parameterState(boolean image,List<TargetId> fallback){return parameterState(image,fallback,TargetResolution.SELECTED_FIRST);}
        public ParameterStateVm parameterState(boolean image,List<TargetId> targets,TargetResolution resolution){
            var all=snapshot().parameters(image);var available=all.states().stream().collect(java.util.stream.Collectors.toMap(ParameterStateVm.TargetState::target,Function.identity()));
            var selected=new ArrayList<TargetId>();
            if(resolution==TargetResolution.SELECTED_FIRST){
                for(var item:workspace().topLevelItems())if(!item.removed()&&item.checked())selected.add(TargetId.ofItem(item.id()));
                for(var group:workspace().groups())for(var item:group.members())if(!item.removed()&&item.checked())selected.add(TargetId.ofItem(item.id()));
                if(selected.isEmpty()&&targets!=null)targets.stream().filter(available::containsKey).findFirst().ifPresent(selected::add);
            }else if(targets!=null)selected.addAll(targets.stream().distinct().filter(available::containsKey).toList());
            var states=selected.stream().map(available::get).toList();
            boolean uniform=states.isEmpty()||states.stream().allMatch(s->Objects.equals(s.config(),states.getFirst().config()));
            return new ParameterStateVm(all.textConfirmed(),all.textGlobal(),all.imageConfirmed(),all.imageGlobal(),selected,selected.size(),states,uniform,states.stream().anyMatch(ParameterStateVm.TargetState::effective));
        }
        public List<PresentationVm> presentation(List<String> paths,AppConfig runtime){return snapshot().presentation().stream().filter(p->paths.contains(p.path())).toList();}
        public PreStartStateVm preStartState(AppConfig runtime,boolean checked){throw new IllegalStateException("Run pre-start query with execute");}
        public ExportSourceVm exportSource(String path){throw new IllegalStateException("Run source query with execute");}
    };
    @Override public WorkspaceCommands commands(){return commands;}
    private final WorkspaceCommands commands=new WorkspaceCommands(){
        public void cancelWorkspaceActivity(){activity(WorkspaceCommands::cancelWorkspaceActivity);}
        public void cancelPreviewLoad(){activity(WorkspaceCommands::cancelPreviewLoad);}
        public void startPreparse(){command(WorkspaceCommands::startPreparse);}
        public void startPreparseFor(List<String> paths){command(c->c.startPreparseFor(List.copyOf(paths)));}
        public void refreshPreparseProgress(){activity(WorkspaceCommands::refreshPreparseProgress);}
        public void loadPreview(String path,boolean confirmed){command(c->c.loadPreview(path,confirmed));}
        public void resolvePreviewRegion(long generation,String path,boolean accepted){command(c->c.resolvePreviewRegion(generation,path,accepted));}
        public void awaitPreviewInFlight(long millis){command(c->c.awaitPreviewInFlight(millis));}
        public void setChecked(List<String> paths,boolean checked){command(c->c.setChecked(paths,checked));}
        public void group(List<String> paths,String name){command(c->c.group(paths,name));}
        public void ungroup(long no){command(c->c.ungroup(no));}
        public void renameGroup(long no,String name){command(c->c.renameGroup(no,name));}
        public void toggleGroupExpanded(long no){command(c->c.toggleGroupExpanded(no));}
        public void setGlobalParams(boolean image,AppConfig config){command(c->c.setGlobalParams(image,config));}
        public void setGroupParams(long no,boolean image,AppConfig config){command(c->c.setGroupParams(no,image,config));}
        public void setItemParams(String path,boolean image,AppConfig config){command(c->c.setItemParams(path,image,config));}
        public void clearParams(List<TargetId> ids,boolean image){command(c->c.clearParams(ids,image));}
        public void applyGlobalParams(TargetId id,boolean image){command(c->c.applyGlobalParams(id,image));}
        public void undo(){command(WorkspaceCommands::undo);}
        public void importPaths(List<String> paths,String source,boolean drag){command(c->c.importPaths(paths,source,drag));}
        public void applyImportPlan(ImportPlanVm plan){command(c->c.applyImportPlan(plan));}
        public void startExtraction(boolean checked){command(c->c.startExtraction(checked));}
        public void cancelExtraction(){cancelExtractionNow();}
        public void clearItems(){command(WorkspaceCommands::clearItems);}
        public void removeItems(List<String> paths){command(c->c.removeItems(paths));}
        public void removeGroup(long no){command(c->c.removeGroup(no));}
        public void setTitleOverride(String path,String title){command(c->c.setTitleOverride(path,title));}
        public void applyParamsToTargets(boolean image,AppConfig config,List<TargetId> ids){command(c->c.applyParamsToTargets(image,config,ids));}
    };
    @Override public void close(){if(!closed.compareAndSet(false,true))return;try{subscription.close();}catch(Exception error){throw new IllegalStateException(error);}finally{requests.shutdownNow();}}
}

package com.mhtextractor.cache;

import com.mhtextractor.i18n.I18n;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.IntConsumer;
import java.util.stream.Stream;

/**
 * 预览缓存生命周期（需求 2 §2.2 四条删除规则的集中实现，§2.6(1)「不得散落 if 判断」）：
 *
 * <ul>
 *   <li>规则 (a)：参数变化 → 删该项目缓存目录（{@link #onParamsChanged}）；</li>
 *   <li>规则 (b)：提取完成 → 删该项目缓存目录（{@link #onExtractionCompleted}，会话 10 接线）；</li>
 *   <li>规则 (c)：项目移除 → 删该项目缓存目录（{@link #onItemRemoved}）；</li>
 *   <li>规则 (d)：退出 → 清空整个会话缓存（{@link #onShutdown}）。</li>
 * </ul>
 *
 * <p>删除按「源文件绝对路径」反查：缓存目录名是单向哈希（{@link PreviewCacheKey#toDirName()}），
 * 无法从路径推目录名，因此经 {@link PreviewCacheStore#listKeys()}（从各目录 meta.json 重建键）扫描匹配。
 * 一次批量操作只需一次扫描（{@link #onItemsRemoved}）。
 *
 * <p>另提供每项目写锁（§2.6(6)）：同一绝对路径恒返回同一把锁，不同项目互不阻塞；
 * 供预览写盘与规则删除之间的互斥使用。
 *
 * <p>会话 12 新增磁盘占用提醒（§2.6(9)）：每跨越一个台阶（默认 10GiB）经 hook 提醒一次，
 * 只提醒不做配额限制；具体 UI 呈现由调用方经 {@link #setSizeAlertHook(IntConsumer)} 注册。
 */
@Slf4j
public class PreviewCacheLifecycle {

    /** 磁盘占用提醒台阶（会话 12）：默认每 10 GiB 一级，二进制口径 10 × 1024³ = 10737418240 字节 */
    public static final long SIZE_ALERT_STEP_BYTES = 10L * 1024 * 1024 * 1024;

    private final PreviewCacheStore store;
    /** 实际生效的提醒台阶（默认 10GiB；测试经包可见构造器注入小值，绕过无法真实写 10GiB 的限制） */
    private final long sizeAlertStepBytes;
    /** 已提醒到的台阶序号（0 = 尚未提醒）：CAS 推进，保证同台阶跨线程只提醒一次 */
    private final AtomicLong lastReportedStep = new AtomicLong(0);
    /** 最近一次检查观测到的总字节数（供 UI 换算「当前实际值」；checkSizeAlert 写，hook 内同步读） */
    private volatile long lastObservedTotalBytes = 0;
    /** 跨台阶回调：参数 = 已跨越的台阶序号（默认台阶下 1=10GiB、2=20GiB…）；null = 未注册（只推进台阶）
     * -- SETTER --
     * 注册磁盘占用提醒回调（会话 12）：跨台阶时在写盘线程同步调用；传 null 卸载。只允许注册一个
     */
    @Setter
    private volatile IntConsumer sizeAlertHook = null;
    /** 每项目写锁注册表（§2.6(6)）：key = 规范化绝对路径 */
    private final ConcurrentHashMap<String, Object> writeLocks = new ConcurrentHashMap<>();

    public PreviewCacheLifecycle(PreviewCacheStore store) {
        this(store, SIZE_ALERT_STEP_BYTES);
    }

    /** 包可见：仅供测试注入小台阶（如 1024 字节）；生产一律走默认 10GiB */
    PreviewCacheLifecycle(PreviewCacheStore store, long sizeAlertStepBytes) {
        this.store = store;
        this.sizeAlertStepBytes = sizeAlertStepBytes;
    }

    public PreviewCacheStore store() {
        return store;
    }

    /** 取某项目的写锁（§2.6(6)）：同一路径恒同一把锁 */
    public Object lockFor(String absolutePath) {
        return writeLocks.computeIfAbsent(normalizePath(absolutePath), _ -> new Object());
    }

    /** 规则 (a)：该项目提取参数变化 → 删除该项目全部缓存目录（含历史指纹的残留目录） */
    public int onParamsChanged(String mhtPath) {
        return deleteAllForPath(mhtPath);
    }

    /** 规则 (a) 批量形态：一次扫描删除多个项目的缓存（全局参数变更/应用到全局/清除参数用） */
    public int onParamsChangedBatch(Collection<String> mhtPaths) {
        return onItemsRemoved(mhtPaths);
    }

    /** 规则 (b)：该项目提取完成 → 删除该项目缓存目录（本会话实现，调用点由会话 10 接线） */
    public int onExtractionCompleted(String mhtPath) {
        return deleteAllForPath(mhtPath);
    }

    /** 规则 (c)：项目从列表移除 → 删除该项目缓存目录 */
    public int onItemRemoved(String mhtPath) {
        return deleteAllForPath(mhtPath);
    }

    /** 规则 (c) 批量形态：一次扫描删除多个项目的缓存（removeItems/removeGroup 用） */
    public int onItemsRemoved(Collection<String> mhtPaths) {
        Set<String> abs = new HashSet<>();
        for (String p : mhtPaths) {
            abs.add(normalizePath(p));
        }
        if (abs.isEmpty()) {
            return 0;
        }
        int deleted = 0;
        try {
            for (PreviewCacheKey key : store.listKeys()) {
                if (abs.contains(key.absolutePath())) {
                    deleted += deleteQuietly(key);
                }
            }
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.01", e.getMessage()));
        }
        logIfDeleted(deleted);
        return deleted;
    }

    /**
     * 规则 (d)：退出前清空整个会话缓存（只清本应用专属根目录，绝不触碰 java.io.tmpdir 整体）。
     * 清空完成后回调 afterCleared（放行关窗用）；IO 失败不抛（退出路径不允许因缓存问题阻止关闭）。
     */
    public void onShutdown(Runnable afterCleared) {
        try {
            store.deleteAll();
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.02", e.getMessage()));
        }
        afterCleared.run();
    }

    /** 启动扫孤儿（P7/P11 崩溃恢复）：删除 .tmp 与无 .complete 的目录；失败不抛（启动路径不因此失败） */
    public int startupCleanup() {
        try {
            return store.cleanupOrphans();
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.03", e.getMessage()));
            return 0;
        }
    }

    // ==================== 磁盘占用提醒（会话 12） ====================

    /** 最近一次台阶检查观测到的总字节数（供 UI 换算「当前实际 GiB」；无任何检查时为 0） */
    public long lastObservedTotalBytes() {
        return lastObservedTotalBytes;
    }

    /**
     * 写盘成功后的磁盘占用提醒检查（会话 12）：计数口径 = 缓存根当前真实总字节数（覆盖写不重复计数）。
     * currentStep = totalBytes / 台阶 → 仅当 currentStep 大于已提醒台阶时用 CAS 抢占，成功者提醒一次。
     * 同台阶内重复调用不触发（幂等）；一次跨越多个台阶只触发一次（参数 = 当前台阶序号）；
     * 并发同台阶调用恰好一次触发。totalBytes 失败静默降级（log.warn），绝不打断预览流程。
     */
    public void checkSizeAlert() {
        long total;
        try {
            total = store.totalBytes();
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.04", e.getMessage()));
            return;
        }
        long currentStep = total / sizeAlertStepBytes;
        long prev;
        while ((prev = lastReportedStep.get()) < currentStep) {
            if (lastReportedStep.compareAndSet(prev, currentStep)) {
                lastObservedTotalBytes = total;
                fireSizeAlert((int) currentStep, total);
                return;
            }
        }
    }

    private void fireSizeAlert(int step, long totalBytes) {
        long stepGiB = step * sizeAlertStepBytes / (1024L * 1024 * 1024);
        log.warn(I18n.msg("log.previewcachelifecycle.05", stepGiB, String.format("%.1f", totalBytes / (1024.0 * 1024 * 1024)), store.root()));
        IntConsumer hook = sizeAlertHook;
        if (hook != null) {
            hook.accept(step);
        }
    }

    /**
     * 是否有未清理的缓存（规则 d 弹窗判定）：根目录下存在任何条目即视为有（含 meta 损坏目录，
     * 它同样需要 deleteAll 才能清除）。判不了（IO 失败）时保守返回 true——宁可多弹一次窗清空兜底。
     */
    public boolean hasCachedEntries() {
        if (!Files.isDirectory(store.root())) {
            return false;
        }
        try (Stream<Path> stream = Files.list(store.root())) {
            return stream.findAny().isPresent();
        } catch (IOException e) {
            return true;
        }
    }

    private int deleteAllForPath(String mhtPath) {
        return onItemsRemoved(List.of(mhtPath));
    }

    private int deleteQuietly(PreviewCacheKey key) {
        try {
            return store.delete(key) ? 1 : 0;
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.06", store.dirFor(key), e.getMessage()));
            return 0;
        }
    }

    private void logIfDeleted(int deleted) {
        if (deleted > 0) {
            log.info(I18n.msg("log.previewcachelifecycle.07", deleted, store.root()));
        }
    }

    private static String normalizePath(String path) {
        return Path.of(path).toAbsolutePath().normalize().toString();
    }
}
package com.mhtextractor.backend;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mhtextractor.util.SourceKinds;

import java.io.IOException;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.FileVisitResult;
import java.nio.file.SimpleFileVisitor;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

/** Session-owned bulk files. Client paths are never used as unrestricted read/delete targets. */
final class IpcFiles implements AutoCloseable {
    private final ObjectMapper json;
    private final Set<Path> issued = new HashSet<>();
    private final Set<Path> borrowed = new HashSet<>();
    final Path root;

    IpcFiles(ObjectMapper json) throws IOException {
        this.json = json.copy().enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
                .enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
        Path configured = Path.of(System.getProperty("java.io.tmpdir")).normalize();
        if (!configured.isAbsolute()) throw new IOException("Absolute temporary path required");
        Files.createDirectories(configured);
        root = Files.createTempDirectory(configured, "mht-ipc-").toRealPath();
    }

    static Path input(String value) throws IOException {
        Path path = absolute(value);
        List<Path> roots = allowedRoots();
        if (roots.isEmpty()) return path;
        Path allowed = allowedRoot(path, roots);
        if (!path.toRealPath().startsWith(allowed)) throw new IllegalArgumentException("Input escapes allowlist");
        // Preflight directory trees, including junctions and symlinks, before the importer can read them.
        if (Files.isDirectory(path)) {
            try (var walk = Files.walk(path)) {
                for (var entries = walk.iterator(); entries.hasNext(); ) {
                    Path entry = entries.next();
                    if (!entry.toRealPath().startsWith(allowed)) {
                        throw new IllegalArgumentException("Input tree escapes allowlist");
                    }
                }
            }
        } else if (SourceKinds.isHtml(path.getFileName().toString())) {
            Path sidecar = path.getParent().resolve(SourceKinds.sidecarDirName(
                    SourceKinds.stripKnownExtension(path.getFileName().toString())));
            if (Files.exists(sidecar, java.nio.file.LinkOption.NOFOLLOW_LINKS)) input(sidecar.toString());
        }
        return path;
    }

    static Path output(String value) throws IOException {
        Path path = checkOutput(value);
        Files.createDirectories(path);
        List<Path> roots = allowedRoots();
        if (!roots.isEmpty() && !path.toRealPath().startsWith(allowedRoot(path, roots))) throw new IllegalArgumentException("Output escapes allowlist");
        return path;
    }

    static Path checkOutput(String value) throws IOException {
        Path path = absolute(value);
        List<Path> roots = allowedRoots();
        if (roots.isEmpty()) return path;
        Path allowed = allowedRoot(path, roots);
        Path ancestor = path;
        while (!Files.exists(ancestor, java.nio.file.LinkOption.NOFOLLOW_LINKS)) ancestor = ancestor.getParent();
        if (!ancestor.toRealPath().startsWith(allowed)) throw new IllegalArgumentException("Output escapes allowlist");
        return path;
    }

    private static Path absolute(String value) {
        Path path = Path.of(value);
        if (!path.isAbsolute()) throw new IllegalArgumentException("Absolute path required");
        return path.normalize();
    }

    private static List<Path> allowedRoots() {
        String configured = System.getProperty("mht.allow.roots");
        if (configured == null) return List.of();
        return java.util.Arrays.stream(configured.split(Pattern.quote(File.pathSeparator), -1))
                .map(IpcFiles::absolute).toList();
    }

    private static Path allowedRoot(Path path, List<Path> roots) {
        return roots.stream().filter(root -> path.startsWith(root) && !path.equals(root))
                .findFirst().orElseThrow(() -> new IllegalArgumentException("Path outside allowlist"));
    }

    private static Path lexical(String value, Path allowed) {
        Path path = absolute(value);
        if (!path.startsWith(allowed) || path.equals(allowed)) throw new IllegalArgumentException("Path outside allowlist");
        return path;
    }

    ObjectNode write(String suffix, byte[] bytes, String mediaType) throws IOException {
        Path file = Files.createTempFile(root, "bulk-", suffix);
        Files.write(file, bytes);
        return issue(file, mediaType);
    }

    JsonNode readUpload(JsonNode ref) throws IOException {
        if (!ref.isObject() || !ref.path("path").isTextual()
                || !ref.path("bytes").isIntegralNumber() || !ref.path("bytes").canConvertToLong()
                || ref.path("bytes").longValue() < 0 || !ref.path("mediaType").asText().equals("application/json")) {
            throw new IllegalArgumentException("JSON FileRef required");
        }
        Path path = lexical(ref.path("path").asText(), root);
        // Validate every ancestor as well: a redirected directory must not reach outside the session.
        if (!path.toRealPath().equals(path) || !Files.isRegularFile(path)
                || Files.size(path) != ref.path("bytes").longValue()) {
            throw new IllegalArgumentException("Invalid upload file");
        }
        return json.readTree(Files.readAllBytes(path));
    }

    ObjectNode issue(Path file, String mediaType) throws IOException {
        Path real = file.toRealPath();
        if (!real.startsWith(root) || !Files.isRegularFile(real)) throw new IOException("Bulk file escapes session");
        issued.add(real);
        return json.createObjectNode().put("path", real.toString()).put("bytes", Files.size(real))
                .put("mediaType", mediaType);
    }

    ObjectNode borrowImage(Path file, String mediaType) throws IOException {
        ObjectNode ref = issue(file, mediaType);
        borrowed.add(file.toRealPath());
        return ref;
    }

    Path validateIssued(String value) throws IOException {
        Path path = lexical(value, root);
        if (!issued.contains(path) || !path.toRealPath().equals(path)) {
            throw new IllegalArgumentException("Path was not issued by this session");
        }
        return path;
    }

    void release(String value) throws IOException {
        Path path = validateIssued(value);
        // Cache images have the preview lifecycle's lease, rather than a bulk-output lease.
        if (!borrowed.remove(path)) Files.delete(path);
        issued.remove(path);
    }

    @Override public void close() throws IOException {
        // Default walkFileTree uses NOFOLLOW_LINKS. Windows junctions can still appear
        // as directories, so reject redirected directories before visiting their children.
        Files.walkFileTree(root, new SimpleFileVisitor<>() {
            @Override public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                if (!dir.toRealPath().equals(dir.toAbsolutePath().normalize())) {
                    Files.delete(dir);
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }

            @Override public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                Files.deleteIfExists(file);
                return FileVisitResult.CONTINUE;
            }

            @Override public FileVisitResult postVisitDirectory(Path dir, IOException failure) throws IOException {
                if (failure != null) throw failure;
                Files.deleteIfExists(dir);
                return FileVisitResult.CONTINUE;
            }
        });
        issued.clear();
    }
}
