        }
        afterCleared.run();
    }

    /** 启动扫孤儿（P7/P11 崩溃恢复）：删除 .tmp 与无 .complete 的目录；失败不抛（启动路径不因此失败） */
    public int startupCleanup() {
        try {
            return store.cleanupOrphans();
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.03", e.getMessage()));
            return 0;
        }
    }

    // ==================== 磁盘占用提醒（会话 12） ====================

    /** 最近一次台阶检查观测到的总字节数（供 UI 换算「当前实际 GiB」；无任何检查时为 0） */
    public long lastObservedTotalBytes() {
        return lastObservedTotalBytes;
    }

    /**
     * 写盘成功后的磁盘占用提醒检查（会话 12）：计数口径 = 缓存根当前真实总字节数（覆盖写不重复计数）。
     * currentStep = totalBytes / 台阶 → 仅当 currentStep 大于已提醒台阶时用 CAS 抢占，成功者提醒一次。
     * 同台阶内重复调用不触发（幂等）；一次跨越多个台阶只触发一次（参数 = 当前台阶序号）；
     * 并发同台阶调用恰好一次触发。totalBytes 失败静默降级（log.warn），绝不打断预览流程。
     */
    public void checkSizeAlert() {
        long total;
        try {
            total = store.totalBytes();
        } catch (IOException e) {
            log.warn(I18n.msg("log.previewcachelifecycle.04", e.getMessage()));
            return;
        }
        long currentStep = total / sizeAlertStepBytes;
        long prev;
        while ((prev = lastReportedStep.get()) < currentStep) {
            if (lastReportedStep.compareAndSet(prev, currentStep)) {
                lastObservedTotalBytes = total;
                fireSizeAlert((int) currentStep, total);
                return;
            }
        }
    }

    private void fireSizeAlert(int step, long totalBytes) {
        long stepGiB = step * sizeAlertStepBytes / (1024L * 1024 * 1024);
        log.warn(I18n.msg("log.previewcachelifecycle.05", stepGiB, String.format("%.1f", totalBytes / (1024.0 * 1024 * 1024)), store.root()));
        IntConsumer hook = sizeAlertHook;
        if (hook != null) {
            hook.accept(step);
        }
    }

    /**
     * 是否有未清理的缓存（规则 d 弹窗判定）：根目录下存在任何条目即视为有（含 meta 损坏目录，
     * 它同样需要 deleteAll 才能清除）。判不了（IO 失败）时保守返回 true——宁可多弹一次窗清空兜底。
     */
    public boolean hasCachedEntries() {

    // ==================== 导入编排事件桥（B5-1）：后端编排驱动的前端刷新 ====================

    /** 端口事件订阅句柄（{@link #initialize()} 挂接；关窗清空缓存时关闭，防止收尾期间再来刷新事件） */
    private AutoCloseable portEvents = () -> { };

    /** 端口事件入口：只消费导入编排事件与后端提醒（其余事件由各自协作者订阅） */
    private void onPortEvent(PortEvent event) {
        if (event instanceof PortEvent.WorkspaceChanged change) { if("FRONTEND_REFRESH".equals(change.kind())) { refs.fileListView().refresh(); return; }
            if (!listInteraction.isDragActive() && !groupCommand.isAnimating()) refreshAfterListChange();
        }
        if (event instanceof PortEvent.ImportRound round) {
            onFx(() -> applyImportRound(round));
        } else if (event instanceof PortEvent.ImportStateChanged state) {
            onFx(() -> applyImportState(state));
        } else if (event instanceof PortEvent.ImportFinished finished) {
            onFx(() -> applyImportFinished(finished));
        } else if (event instanceof PortEvent.Notice notice) {
            applyNotice(notice);
        } else if (event instanceof PortEvent.ExtractionChannelEvent extraction) {
            onFx(() -> extractionCoordinator.applyExtractionEvent(extraction));
        }
    }

    /** 后端事件可能来自导入后台线程：FX 线程直接执行，否则转投（顺序由事件流保证） */
    private void onFx(Runnable task) {
        if (Platform.isFxApplicationThread()) {
            task.run();
        } else {
            Platform.runLater(task);
        }
    }

    // ==================== 辅助 ====================

    /**
     * 会话 12：磁盘占用跨台阶回调（在预览后台线程被 checkSizeAlert 同步调用）。
     * 台阶序号换算 GiB、取当前实际占用后，回 FX 线程弹<b>右上角非阻塞 toast</b>
     * （会话 19：原非模态 Alert 换成应用内提醒；连续跨台阶由 toast 图层自行限流，不再需要"先关再弹"）。
     */
    void onSizeAlertStep(int step) {
        long stepGiB = step * 10L * 1024 * 1024 * 1024 / (1024L * 1024 * 1024);
        double actualGiB = activityPort.queries().cacheState().totalBytes() / (1024.0 * 1024 * 1024);
        String message = Texts.get("cache.sizeAlert",
                        "step", stepGiB, "actual", String.format("%.1f", actualGiB),
                        "dir", activityPort.queries().cacheState().root())
                + Texts.get("cache.sizeAlertNote");
        GuiNotifications.cacheStepWarning(refs.statusLabel(), message);
    }
}
