     */
    private static final ThreadLocal<Boolean> IN_MSG = ThreadLocal.withInitial(() -> Boolean.FALSE);

    private I18n() {
    }

    /**
     * 日志文案入口：占位符为<b>位置索引</b> {@code {0}} {@code {1}} …（{@code log.*} 调用点专用）。
     *
     * <p>与 {@link #get(String, Object...)} 的具名占位符同一渲染引擎（{@code \w+} 本就覆盖数字），
