                .put("version", identity.version()).put("buildId", identity.buildId())).path("result");
        assertEquals(ready.path("data").path("sessionId"), welcome.path("sessionId"));
        bulkRoot = Path.of(welcome.path("bulkRoot").asText()); revision = 0;
